const ICONS = [['play-gate','Play'],['garage','Garage'],['collection','Collection'],['brainrot','Brainrot'],['egg','Eggs'],['shop','Shop'],['social','Social'],['trade','Trading'],['inspect','Inspect'],['royal','Royal'],['founder','Founder'],['event','Event'],['season','Season'],['surge','Neon Surge'],['trail','Trail'],['underglow','Underglow'],['aura','Aura'],['boost','Boost'],['coins','Coins'],['xp','XP'],['level','Level'],['equip','Equipped'],['locked','Locked'],['settings','Settings'],['leaderboard','Ranking'],['daily','Daily'],['reward','Reward'],['map','Maps']];
const state={page:'home',tabs:{collection:'brainrot',shop:'featured',social:'nearby',garage:'bike'},bike:'pulse',brainrot:'TralaleroTralala',wallet:12450,ownedBikes:new Set(['pulse','magma']),ownedBrainrots:new Set(['TralaleroTralala','BananaBot','ToasterGoblin','SixSeven']),ownedTrails:new Set(['clean']),equippedTrail:'clean',boosting:false,battleResult:false,tradeStep:0,tradeOffer:'BananaBot',claim:false};
state.slotValues={Underglow:'Electric Cyan',Aura:'Neon Pulse','Boost FX':'Overdrive'};
const stage=document.getElementById('stage');
const modalRoot=document.getElementById('modal-root');
const money=n=>new Intl.NumberFormat('it-IT').format(n);
const icon=id=>`<img src="icons/${id}.svg" alt="">`;
const bike=id=>BIKES.find(x=>x.id===id);
const brainrot=id=>BRAINROTS.find(x=>x.id===id);
const trail=id=>TRAILS.find(x=>x.id===id);
const bundlePrice=b=>Math.round(((state.ownedBikes.has(b.bike)?0:bike(b.bike).price)+(state.ownedTrails.has(b.trail)?0:trail(b.trail).price))*.82);
const rarity=r=>`<span class="rarity ${r}">${r}</span>`;
const header=(tag,title,desc,actions='')=>`<div class="screen-header"><div><p class="eyebrow">${tag}</p><h2>${title}</h2><p>${desc}</p></div>${actions?`<div class="header-actions">${actions}</div>`:''}</div>`;
const tabs=(page,items)=>`<div class="tabs" role="tablist">${items.map(([id,label])=>`<button class="tab ${state.tabs[page]===id?'active':''}" role="tab" aria-selected="${state.tabs[page]===id}" data-tab="${page}:${id}">${label}</button>`).join('')}</div>`;
const bikeCard=(b,mode='collection')=>`<button class="product-card" data-rarity="${b.rarity}" data-detail="bike:${b.id}" data-name="${b.name.toLowerCase()}"><div class="product-art"><img src="${b.img}" alt="Render Tripo di ${b.name}" loading="lazy"><span class="product-badge">${state.ownedBikes.has(b.id)?'OWNED':'VIEW'}</span></div><div class="product-info">${rarity(b.rarity)}<strong>${b.name}</strong><small class="${mode==='shop'?'price':''}">${mode==='shop'?`${b.price===0?'FREE':`${money(b.price)} COINS`}`:state.ownedBikes.has(b.id)?'Nella tua collection demo':'Da scoprire'}</small></div></button>`;
const brainrotCard=b=>`<button class="product-card brainrot" data-rarity="${b.rarity}" data-detail="brainrot:${b.id}" data-name="${b.name.toLowerCase()}"><div class="product-art"><img src="${b.img}" alt="Render Tripo di ${b.name}" loading="lazy"><span class="product-badge">${state.ownedBrainrots.has(b.id)?'OWNED':'DISCOVER'}</span></div><div class="product-info">${rarity(b.rarity)}<strong>${b.name}</strong><small>${state.ownedBrainrots.has(b.id)?'In collection demo':'Non posseduto nella demo'}</small></div></button>`;
const bundleCard=b=>`<button class="bundle-card" style="--bundle-color:${b.color}" data-detail="bundle:${b.id}"><div class="bundle-art"><img src="${bike(b.bike).img}" alt="Render Tripo della moto ${bike(b.bike).name}" loading="lazy"><span class="product-badge">BIKE + TRAIL</span></div><div class="content"><strong>${b.name}</strong><small>${b.tag}</small><em>${bundlePrice(b)===0?'COMPLETATO':`${money(bundlePrice(b))} COINS · DEMO`}</em></div></button>`;
function home(){return `<div class="hero"><div class="hero-copy"><p class="eyebrow">CENTRAL PLAZA / READY TO RIDE</p><h2>LA CITTÀ<br>È TUA.</h2><p>Entra in arena, mostra la tua moto e porta con te il brainrot che hai scelto.</p><div class="button-row"><button class="button" data-page="battle">▶ PLAY MATCH</button><button class="outline" data-page="garage">APRI GARAGE</button></div></div><img class="hero-bike" src="${bike(state.bike).img}" alt="Moto Tripo ${bike(state.bike).name}"><button class="hero-brainrot" data-detail="brainrot:${state.brainrot}"><img src="${brainrot(state.brainrot).img}" alt="Brainrot Tripo ${brainrot(state.brainrot).name}"><span>${brainrot(state.brainrot).name}</span></button></div><div class="home-lower"><div class="card card-pad">${icon('daily')}<span class="mini-label">NEXT OBJECTIVE</span><h3>2 gare per la ricompensa</h3><p>Missione giornaliera demo · progressi 1/3</p><div class="progress-track" style="--progress:33%;margin-top:12px"><i></i></div></div><button class="card card-pad" data-page="shop" style="text-align:left;color:white">${icon('reward')}<span class="mini-label">FEATURED BUNDLE</span><h3>Arcade Drive</h3><p>Moto Tripo + Circuit Trace</p></button><button class="card card-pad" data-page="social" style="text-align:left;color:white">${icon('social')}<span class="mini-label">SOCIAL PLAZA</span><h3>3 rider vicini</h3><p>Inspect e Trading in anteprima</p></button></div>`}
function collection(){const tab=state.tabs.collection;let content='';if(tab==='brainrot')content=`<div class="toolbar"><p>20 modelli Tripo · tocca una card per Inspect</p><input class="search" data-search placeholder="Cerca brainrot" aria-label="Cerca brainrot"></div><div class="asset-grid" id="search-grid">${BRAINROTS.map(brainrotCard).join('')}</div>`;if(tab==='bikes')content=`<div class="toolbar"><p>16 modelli Tripo · rendersi conto della scala e del look</p><input class="search" data-search placeholder="Cerca moto" aria-label="Cerca moto"></div><div class="asset-grid" id="search-grid">${BIKES.map(b=>bikeCard(b)).join('')}</div>`;if(tab==='eggs')content=`<div class="egg-grid">${EGGS.map(e=>`<button class="egg-card card" data-detail="egg:${e.id}" style="color:white"><div class="egg-shape" style="--egg-texture:url('${e.texture}')"></div><strong>${e.name}</strong><p>${e.desc}</p><span class="mini-label">VEDI POOL ↗</span></button>`).join('')}</div>`;if(tab==='items')content=`<div class="asset-grid">${TRAILS.map(t=>`<button class="product-card" data-detail="trail:${t.id}" data-rarity="${t.rarity}"><div class="product-art" style="--trail-color:${t.color}"><div class="trail-preview"></div></div><div class="product-info">${rarity(t.rarity)}<strong>${t.name}</strong><small>Trail cosmetico</small></div></button>`).join('')}</div>`;return header('COLLECTION / MODELS FROM TRIPO','La tua collection','Moto e brainrot mostrati con render ricavati dai rispettivi GLB Tripo. Possesso e progressi qui sono dati dimostrativi.',`<button class="outline small" data-page="garage">Vai al Garage ↗</button>`)+tabs('collection',[['brainrot','Brainrot · 20'],['bikes','Bikes · 16'],['eggs','Eggs'],['items','Trails']])+content}
function garage(){const b=bike(state.bike);return header('GARAGE / YOUR RIDE','Garage','Scegli una moto Tripo, confronta la livrea e prova l’effetto Boost nel prototipo.',`<button class="outline small" data-page="collection">Tutte le moto ↗</button>`)+`<div class="garage-layout"><div><div class="garage-view ${state.boosting?'boosting':''}"><img src="${b.img}" alt="Render Tripo di ${b.name}"><span class="view-tag">${b.name} · ${b.rarity}</span><div class="view-note"><span>${state.boosting?'BOOST FX ATTIVO · ANTEPRIMA':'RENDER DEL MODELLO TRIPO'}</span><span>VISUAL DEMO</span></div></div><div class="bike-strip">${BIKES.map(x=>`<button class="bike-pick ${x.id===b.id?'active':''}" data-action="select-bike" data-id="${x.id}"><img src="${x.img}" alt=""><span>${x.name}</span></button>`).join('')}</div></div><div class="garage-side"><div class="card card-pad"><span class="mini-label">BIKE SELECTED</span><h3 style="font-size:24px;margin:7px 0 2px">${b.name}</h3>${rarity(b.rarity)}<p style="margin:10px 0">${state.ownedBikes.has(b.id)?'Posseduta nella demo':'Anteprima della moto. Apri lo Shop per vedere il prezzo.'}</p><div class="button-row"><button class="button small" data-action="equip-bike" data-id="${b.id}">${state.ownedBikes.has(b.id)?'EQUIPAGGIA':'VEDI NELLO SHOP'}</button><button class="outline small" data-action="boost">${state.boosting?'FERMA BOOST':'TEST BOOST'}</button></div></div><div class="card card-pad"><span class="mini-label">COSMETIC SLOTS</span>${[['trail','Trail',trail(state.equippedTrail).name],['underglow','Underglow',state.slotValues.Underglow],['aura','Aura',state.slotValues.Aura],['boost','Boost FX',state.slotValues['Boost FX']]].map(([ico,name,value])=>`<div class="slot-row">${icon(ico)}<div class="slot-name"><b>${name}</b><small>${value}</small></div><button class="quiet small" data-action="slot" data-id="${name}">EDIT ↗</button></div>`).join('')}</div></div></div>`}
function shop(){const tab=state.tabs.shop;let content='';if(tab==='featured')content=`<div class="feature-grid"><div class="feature-bundle"><div class="copy"><span class="mini-label" style="color:#ffd0ed">FEATURED / BIKE + TRAIL</span><h3>SUGAR<br>RUSH</h3><p>La moto Tripo Sugar Rush con Pinstripe. Contenuto garantito nel bundle.</p><button class="button pink small" data-detail="bundle:candy_run">ESPLORA BUNDLE</button></div><img src="${bike('sugarrush').img}" alt="Render Tripo Sugar Rush"></div><div class="card card-pad" style="display:flex;flex-direction:column;justify-content:space-between"><div><span class="mini-label">HOW SHOP WORKS</span><h3 style="font-size:24px;margin-top:8px">Vedi cosa ottieni prima di scegliere.</h3><p>Ogni bundle mostra la moto e la scia incluse. Il prezzo si aggiorna se possiedi già un pezzo.</p></div><button class="outline" data-tab="shop:bundles">CONFRONTA I 5 BUNDLE →</button></div></div><div class="section-heading"><div><p class="overline">FIVE GUARANTEED SETS</p><h3>Bundles</h3></div><button class="quiet" data-tab="shop:bundles">Vedi tutti →</button></div><div class="bundle-grid">${BUNDLES.map(bundleCard).join('')}</div><div class="section-heading"><div><p class="overline">TRIPO MODEL PREVIEW</p><h3>Bikes in evidenza</h3></div><button class="quiet" data-tab="shop:bikes">Catalogo completo →</button></div><div class="asset-grid">${['magma','interstellar','angelica','arcade'].map(id=>bikeCard(bike(id),'shop')).join('')}</div>`;if(tab==='bundles')content=`<p class="muted" style="font-size:12px">5 bundle configurati · il prezzo mostrato usa il possesso fittizio di questa demo e la formula del progetto.</p><div class="bundle-grid">${BUNDLES.map(bundleCard).join('')}</div>`;if(tab==='bikes')content=`<div class="toolbar"><p>Catalogo moto Tripo con i prezzi Coins configurati.</p><input class="search" data-search placeholder="Cerca moto" aria-label="Cerca moto"></div><div class="asset-grid" id="search-grid">${BIKES.map(b=>bikeCard(b,'shop')).join('')}</div>`;if(tab==='trails')content=`<div class="asset-grid">${TRAILS.map(t=>`<button class="product-card" data-rarity="${t.rarity}" data-detail="trail:${t.id}"><div class="product-art" style="--trail-color:${t.color}"><div class="trail-preview"></div></div><div class="product-info">${rarity(t.rarity)}<strong>${t.name}</strong><small class="price">${t.price===0?'FREE':`${money(t.price)} COINS`}</small></div></button>`).join('')}</div>`;return header('SHOP / CURATED GEAR','Shop','Bundle, moto e scie con contenuto chiaro e anteprima visiva. Gli acquisti qui aggiornano solo la demo.',`<button class="outline small" data-page="collection">Apri Collection ↗</button>`)+tabs('shop',[['featured','Featured'],['bundles','Bundles · 5'],['bikes','Bikes · 16'],['trails','Trails']])+content}
function social(){const tab=state.tabs.social;let content='';if(tab==='nearby')content=`<div class="social-layout"><div class="stack"><div class="card card-pad"><span class="mini-label">NEARBY / CENTRAL PLAZA</span><h3 style="margin-top:6px">Rider nelle vicinanze</h3><p>Seleziona un giocatore per vedere equipaggiamento e collezione visibile.</p></div>${[['N','NEON_NOVA','Royal Rider · Lv 31'],['L','LUNA_VOLT','Founder · Lv 27'],['K','KAI_ARCADE','Rider · Lv 18']].map(([letter,name,sub])=>`<div class="person-row"><span class="avatar">${letter}</span><span><strong>${name}</strong><small>${sub}</small></span><button class="outline small" data-action="inspect-player" data-id="${name}">INSPECT</button></div>`).join('')}</div><div class="card card-pad"><span class="mini-label">SOCIAL ACTIONS</span><h3 style="font-size:23px;margin-top:7px">Guarda. Confronta. Scambia.</h3><p>L’Inspect mostra il profilo prima di ogni invito. La demo di Trading simula offerte, Ready e conferma finale.</p><div class="divider"></div><div class="button-row"><button class="button small" data-tab="social:inspect">PROVA INSPECT</button><button class="outline small" data-tab="social:trading">PROVA TRADING</button></div></div></div>`;if(tab==='inspect')content=`<div class="card card-pad"><div class="person-row" style="background:transparent;border:0;padding:0 0 15px"><span class="avatar">N</span><span><strong>NEON_NOVA</strong><small>Royal Rider · Lv 31 · Esempio</small></span><button class="outline small" data-tab="social:trading">INVITA A TRADE</button></div><div class="social-profile"><div class="profile-art"><img src="${bike('interstellar').img}" alt="Moto Tripo Interstellar"></div><div class="profile-art"><img src="${brainrot('VolpinaVoltVolt').img}" alt="Brainrot Tripo Volpina Volt Volt"></div></div><div style="display:flex;justify-content:space-between;margin-top:10px"><span><span class="mini-label">BIKE</span><br><strong>INTERSTELLAR</strong></span><span><span class="mini-label">BRAINROT</span><br><strong>VOLPINA VOLT VOLT</strong></span></div></div>`;if(tab==='trading')content=`<div class="card card-pad"><span class="mini-label">TRADING / FLOW DEMO</span><h3 style="font-size:23px;margin-top:7px">Offerta tra due rider</h3><p>Scegli il tuo Brainrot, verifica entrambi i lati e prova la doppia conferma.</p><div class="divider"></div><div class="trade-board"><div class="trade-offer"><span class="mini-label">LA TUA OFFERTA</span><img src="${brainrot(state.tradeOffer).img}" alt="${brainrot(state.tradeOffer).name}"><strong>${brainrot(state.tradeOffer).name}</strong><button class="quiet small" data-action="change-offer">CAMBIA ↗</button></div><div class="trade-vs">⇄</div><div class="trade-offer"><span class="mini-label">NEON_NOVA OFFRE</span><img src="${brainrot('VolpinaVoltVolt').img}" alt="Volpina Volt Volt"><strong>Volpina Volt Volt</strong><small class="muted">Offerta simulata</small></div></div><div class="status-line"><span class="pulse-dot"></span>${state.tradeStep===0?'Controlla le offerte prima di premere Ready.':state.tradeStep===1?'Tu sei Ready. L’altro rider è Ready nella demo.':'Conferma finale: entrambe le parti devono accettare.'}</div><div class="button-row" style="margin-top:15px"><button class="button small" data-action="trade-next">${state.tradeStep===0?'SONO READY':state.tradeStep===1?'RIVEDI E CONFERMA':'CONFERMA SCAMBIO DEMO'}</button><button class="outline small" data-action="trade-reset">ANNULLA</button></div></div>`;return header('SOCIAL / INSPECT / TRADING','Social Plaza','Un luogo per vedere le collezioni degli altri rider e provare il flusso di scambio.',`<button class="outline small" data-page="garage">Il mio Garage ↗</button>`)+tabs('social',[['nearby','Nearby'],['inspect','Inspect'],['trading','Trading']])+content}
function battle(){return header('BATTLE / FOCUSED HUD','Arena','Durante la guida la UI lascia spazio alla strada: posizione, tempo, piloti e Boost.',`<button class="outline small" data-page="home">Torna in lobby</button>`)+(state.battleResult?`<div class="card result-panel"><p class="eyebrow">MATCH RESULT / DEMO</p><h3>#03 / 08</h3><p>La schermata risultati evidenzia posizione, Coins, XP e progresso missioni.</p><div class="button-row" style="justify-content:center;margin-top:20px"><button class="button" data-action="battle-again">RIGIOCA DEMO</button><button class="outline" data-page="collection">VEDI RICOMPENSE</button></div></div>`:`<div class="battle-stage"><div class="hud-top"><strong>04:32</strong><small>6 RIDER VIVI</small></div><div class="hud-controls"><button class="outline small" data-action="battle-result">SIMULA FINE GARA →</button></div><img class="battle-bike" src="${bike(state.bike).img}" alt="Moto Tripo in gara"><div class="hud-left">#03 <span style="color:#96bbce">/ 08</span></div><div class="hud-right">⚡ BOOST 80%</div></div><p class="muted" style="font-size:11px;margin-top:12px">Scena di anteprima: la gara vera è nel gioco Roblox, questa pagina mostra la proposta di HUD.</p>`)}
function royal(){return header('ROYAL / STATUS & REWARDS','Royal Hall','Una pagina distinta dalla Collection e dal Founder: benefici e ricompense chiari.',`<button class="outline small" data-page="events">Eventi ↗</button>`)+`<div class="feature-grid"><div class="card card-pad" style="background:radial-gradient(circle at 80% 40%,#80622d77,transparent 45%),linear-gradient(130deg,#382947,#12233e);border-color:#b9955b"><span class="mini-label accent-gold">ROYAL STATUS / DEMO</span><h3 style="font:900 43px 'Barlow Condensed',Impact,sans-serif;margin:10px 0;color:#ffe2a1">THE ROYAL RIDE</h3><p>Identità visiva premium senza confondere i cosmetici Founder con le ricompense Royal.</p><div class="button-row" style="margin-top:20px"><button class="button gold small" data-action="royal-claim">${state.claim?'RICOMPENSA RISCATTATA':'RISCATTA RICOMPENSA DEMO'}</button></div></div><div class="card card-pad"><span class="mini-label">ROYAL REWARD PREVIEW</span><div class="egg-shape" style="--egg-texture:url('${EGGS[3].texture}')"></div><h3 style="text-align:center">Skyline Seraph</h3><p style="text-align:center">L’uovo Royal in anteprima visiva.</p></div></div><div class="section-heading"><h3>Percorso Royal</h3></div><div class="asset-grid">${[['royal','Royal status','Identità e cornice'],['egg','Egg Hall','Pool e drop leggibili'],['reward','Weekly reward','Ricompensa visibile'],['founder','Founder','Distintivo separato']].map(([ico,title,desc])=>`<div class="card card-pad">${icon(ico)}<h3 style="margin-top:10px">${title}</h3><p>${desc}</p></div>`).join('')}</div>`}
function events(){return header('WORLD EVENTS / SEASON','Events','Scopri il prossimo evento, le sfide stagionali e le ricompense prima di entrare in gara.',`<button class="outline small" data-page="missions">Le missioni ↗</button>`)+`<div class="feature-grid"><div class="card card-pad" style="background:linear-gradient(120deg,#4a184e,#101e3e);border-color:#b65ca5"><span class="mini-label accent-pink">WORLD EVENT / SAMPLE</span><h3 style="font:900 42px 'Barlow Condensed',Impact,sans-serif;margin:10px 0">CORE CRASH</h3><p>Anteprima del banner evento. Entrando puoi vedere regole, obiettivo e ricompense.</p><button class="button pink small" style="margin-top:18px" data-action="event-detail">VEDI DETTAGLI</button></div><div class="card card-pad"><span class="mini-label">SEASON TRACK / SAMPLE</span><h3 style="font-size:23px;margin:8px 0">Neon Season 01</h3><p>Livello 12 / 30</p><div class="progress-track" style="--progress:40%;margin:16px 0"><i></i></div><p>La reward successiva resta visibile anche dalla lobby.</p></div></div><div class="section-heading"><h3>Ricompense in anteprima</h3></div><div class="asset-grid">${[brainrot('SemaforinoSprint'),brainrot('RamenMeteorino')].map(brainrotCard).join('')}${['manta','phoenix'].map(id=>bikeCard(bike(id))).join('')}</div>`}
function missions(){return header('DAILY / PROGRESSION','Missions','Obiettivi brevi con avanzamento leggibile. I numeri qui servono a provare la UI.',`<button class="outline small" data-page="battle">Vai in Battle ↗</button>`)+`<div class="feature-grid"><div class="card"><div class="mission-row">${icon('play-gate')}<div class="mission-body"><strong>Completa 3 gare</strong><small>1 / 3 · ricompensa 120 Coins</small><div class="progress-track" style="--progress:33%;margin-top:8px"><i></i></div></div></div><div class="mission-row">${icon('boost')}<div class="mission-body"><strong>Usa Boost 5 volte</strong><small>3 / 5 · ricompensa 70 XP</small><div class="progress-track" style="--progress:60%;margin-top:8px"><i></i></div></div></div><div class="mission-row">${icon('inspect')}<div class="mission-body"><strong>Inspect un rider</strong><small>0 / 1 · ricompensa 50 Coins</small><div class="progress-track" style="--progress:0%;margin-top:8px"><i></i></div></div></div></div><div class="card card-pad"><span class="mini-label">NEXT LEVEL</span><h3 style="font-size:25px;margin:8px 0">Rider Lv 23</h3><p>Una traccia semplice che collega partite, Collection e ricompense.</p><div class="progress-track" style="--progress:72%;margin:18px 0"><i></i></div><button class="outline small" data-page="collection">VEDI COLLECTION →</button></div></div>`}
function leaderboard(){return header('RANKING / COMMUNITY','Leaderboard','Posizione, punti e identità del rider con i titoli ben distinguibili.',`<button class="outline small" data-page="social">Vai al Social ↗</button>`)+`<div class="card"><div class="leader-row"><span class="mini-label">POS</span><span></span><span class="mini-label">RIDER</span><span class="mini-label">POINTS</span></div>${[['01','N','NEON_NOVA','Royal Rider','18.400'],['02','L','LUNA_VOLT','Founder','16.920'],['03','O','OSCAR','Rider','15.650'],['04','K','KAI_ARCADE','Rider','13.280'],['05','V','VIOLET_RUN','Rider','11.870']].map(([rank,letter,name,title,score])=>`<div class="leader-row"><b>${rank}</b><span class="avatar">${letter}</span><span><strong>${name}</strong><br><small class="muted">${title}</small></span><b>${score}</b></div>`).join('')}</div>`}
const pages={home,collection,garage,shop,social,battle,royal,events,missions,leaderboard};
function render(){document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));document.getElementById('wallet-value').textContent=money(state.wallet);stage.innerHTML=pages[state.page]();}
function go(page){if(!pages[page])return;state.page=page;render();stage.scrollIntoView({behavior:'smooth',block:'nearest'});history.replaceState(null,'',`?page=${page}`)}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.hidden=true,3500)}
function openModal(title,body){modalRoot.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><div><p class="eyebrow">NEON SURVIVORS / PREVIEW</p><h2>${title}</h2></div><button class="quiet" data-action="close-modal" aria-label="Chiudi">✕</button></div><div class="modal-body">${body}</div></div>`;modalRoot.hidden=false;document.body.style.overflow='hidden';modalRoot.querySelector('[data-action="close-modal"]').focus()}
function closeModal(){modalRoot.hidden=true;modalRoot.innerHTML='';document.body.style.overflow=''}
function showPlayer(id){const players={NEON_NOVA:{initial:'N',title:'Royal Rider · Lv 31',bike:'interstellar',brainrot:'VolpinaVoltVolt'},LUNA_VOLT:{initial:'L',title:'Founder · Lv 27',bike:'angelica',brainrot:'ToasterGoblin'},KAI_ARCADE:{initial:'K',title:'Rider · Lv 18',bike:'arcade',brainrot:'SixSeven'}};const p=players[id];if(!p)return;openModal(id,`<div class="person-row" style="margin-bottom:14px"><span class="avatar">${p.initial}</span><span><strong>${id}</strong><small>${p.title} · profilo dimostrativo</small></span></div><div class="social-profile"><div class="profile-art"><img src="${bike(p.bike).img}" alt="Moto Tripo ${bike(p.bike).name}"></div><div class="profile-art"><img src="${brainrot(p.brainrot).img}" alt="Brainrot Tripo ${brainrot(p.brainrot).name}"></div></div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:12px"><span><span class="mini-label">BIKE</span><br><strong>${bike(p.bike).name}</strong></span><span><span class="mini-label">BRAINROT</span><br><strong>${brainrot(p.brainrot).name}</strong></span></div><div class="button-row" style="margin-top:17px"><button class="button small" data-action="inspect-to-trade">PROVA TRADING</button><button class="outline small" data-action="close-modal">CHIUDI</button></div>`)}
function showSlot(id){if(id==='Trail'){state.tabs.shop='trails';go('shop');return}const choices=id==='Underglow'?['Electric Cyan','Hot Magenta','Royal Gold']:id==='Aura'?['Neon Pulse','Starfall','Ember Halo']:['Overdrive','Ion Flash','Comet Dash'];openModal(`${id} / Cosmetic slot`,`<p class="muted">Scegli un'opzione per vedere come si presenterebbe nello slot del Garage. Gli effetti sono illustrativi.</p><div class="stack">${choices.map((choice,index)=>`<button class="card card-pad" style="display:flex;align-items:center;gap:13px;color:white;text-align:left" data-action="slot-select" data-id="${id}:${choice}"><span class="item-visual" style="margin:0;background:${['#17627d','#6c2f76','#826034'][index]}">${icon(id==='Underglow'?'underglow':id==='Aura'?'aura':'boost')}</span><span><strong>${choice}</strong><br><small class="muted">${choice===state.slotValues[id]?'Selezionato nella demo':'Prova nel Garage'}</small></span></button>`).join('')}</div>`)}
function detail(type,id){if(type==='bike'){const b=bike(id);openModal(b.name,`<div class="detail-layout"><div class="detail-art"><img src="${b.img}" alt="Render del modello Tripo ${b.name}"></div><div class="detail-copy">${rarity(b.rarity)}<p>Render ricavato dal GLB Tripo della moto. In Roblox la scheda finale potrà usare la preview 3D in tempo reale.</p><ul><li>Modello: ${b.name}</li><li>Prezzo configurato: ${b.price?`${money(b.price)} Coins`:'gratuita'}</li><li>Stato demo: ${state.ownedBikes.has(b.id)?'posseduta':'non posseduta'}</li></ul><div class="button-row modal-actions"><button class="button small" data-action="bike-primary" data-id="${b.id}">${state.ownedBikes.has(b.id)?'EQUIPAGGIA':'ACQUISTA NELLA DEMO'}</button><button class="outline small" data-action="view-garage" data-id="${b.id}">VEDI IN GARAGE</button></div></div></div>`)}
else if(type==='brainrot'){const b=brainrot(id);openModal(b.name,`<div class="detail-layout"><div class="detail-art"><img src="${b.img}" alt="Render del modello Tripo ${b.name}"></div><div class="detail-copy">${rarity(b.rarity)}<p>Render del GLB Tripo del Brainrot. Rarità e nome seguono il manifest del progetto.</p><ul><li>Stato demo: ${state.ownedBrainrots.has(b.id)?'in collection':'da scoprire'}</li><li>Origine: collection Brainrot</li><li>Uso: compagno visibile in lobby e Inspect</li></ul><div class="button-row modal-actions"><button class="button small" data-action="brainrot-equip" data-id="${b.id}" ${state.ownedBrainrots.has(b.id)?'':'disabled'}>${state.ownedBrainrots.has(b.id)?'MOSTRA IN LOBBY':'NON POSSEDUTO'}</button><button class="outline small" data-action="close-modal">CHIUDI</button></div></div></div>`)}
else if(type==='bundle'){const b=BUNDLES.find(x=>x.id===id);const cost=bundlePrice(b);openModal(b.name,`<div class="detail-layout"><div class="detail-art" style="background:radial-gradient(circle at 50% 65%,${b.color}77,transparent 55%),#0b1b32"><img src="${bike(b.bike).img}" alt="Render Tripo ${bike(b.bike).name}"></div><div class="detail-copy"><span class="mini-label">GUARANTEED BUNDLE / BIKE + TRAIL</span><p>${b.tag}. Contenuto del bundle letto dalla configurazione del progetto.</p><ul><li>Moto Tripo: <strong>${bike(b.bike).name}</strong> ${state.ownedBikes.has(b.bike)?'· già posseduta':''}</li><li>Trail: <strong>${trail(b.trail).name}</strong> ${state.ownedTrails.has(b.trail)?'· già posseduta':''}</li><li>Prezzo demo: <strong>${money(cost)} Coins</strong></li></ul><p style="font-size:11px">Prezzo ricalcolato sui pezzi mancanti: 82% della somma, come nel BundleConfig.</p><div class="button-row modal-actions"><button class="button small" data-action="buy-bundle" data-id="${b.id}" ${cost===0?'disabled':''}>${cost===0?'GIÀ COMPLETATO':'ACQUISTA NELLA DEMO'}</button><button class="outline small" data-action="view-garage" data-id="${b.bike}">VEDI MOTO</button></div></div></div>`)}
else if(type==='trail'){const t=trail(id);openModal(t.name,`<div class="detail-layout"><div class="detail-art" style="--trail-color:${t.color}"><div class="trail-preview"></div></div><div class="detail-copy">${rarity(t.rarity)}<p>Rappresentazione UI della scia cosmetica. L’effetto di gioco effettivo va verificato nel client Roblox.</p><ul><li>Prezzo configurato: ${money(t.price)} Coins</li><li>Stato demo: ${state.ownedTrails.has(t.id)?'posseduto':'non posseduto'}</li></ul><div class="button-row modal-actions"><button class="button small" data-action="trail-primary" data-id="${t.id}">${state.ownedTrails.has(t.id)?'EQUIPAGGIA':'ACQUISTA NELLA DEMO'}</button></div></div></div>`)}
else if(type==='egg'){const e=EGGS.find(x=>x.id===id);openModal(e.name,`<div class="detail-layout"><div class="detail-art"><div class="egg-shape" style="--egg-texture:url('${e.texture}');transform:scale(1.35)"></div></div><div class="detail-copy"><span class="mini-label">EGG HALL / VISUAL PREVIEW</span><p>${e.desc}. La texture viene dagli asset locali delle uova. Questa schermata propone come presentare pool e probabilità.</p><ul><li>Pool: visibile prima dell’apertura</li><li>Rarità: associate ai Brainrot Tripo</li><li>Risultato: scheda reveal con modello</li></ul><button class="outline small" data-action="egg-pool" data-id="${e.id}">ANTEPRIMA POOL</button></div></div>`)}
}
function action(name,id){switch(name){case'close-modal':closeModal();break;case'open-icons':document.getElementById('icons-section').hidden=false;document.getElementById('icons-section').scrollIntoView({behavior:'smooth'});break;case'close-icons':document.getElementById('icons-section').hidden=true;break;case'select-bike':state.bike=id;state.boosting=false;render();break;case'equip-bike':if(state.ownedBikes.has(id)){state.bike=id;showToast(`${bike(id).name} equipaggiata nella demo.`);render()}else{state.tabs.shop='bikes';go('shop')}break;case'boost':state.boosting=!state.boosting;render();showToast(state.boosting?'Boost visivo attivo nella demo.':'Boost visivo fermato.');break;case'slot':showSlot(id);break;case'slot-select':{const [slot,value]=id.split(':');state.slotValues[slot]=value;closeModal();render();showToast(`${value} selezionato nello slot ${slot} della demo.`);break}case'inspect-to-trade':closeModal();state.tabs.social='trading';go('social');break;case'bike-primary':{const b=bike(id);if(!state.ownedBikes.has(id)){if(b.price>state.wallet){showToast('Coins demo insufficienti.');break}state.wallet-=b.price;state.ownedBikes.add(id)}state.bike=id;closeModal();render();showToast(`${b.name} equipaggiata nella demo.`);break}case'view-garage':state.bike=id;closeModal();go('garage');break;case'brainrot-equip':state.brainrot=id;closeModal();go('home');showToast(`${brainrot(id).name} ora appare nella lobby demo.`);break;case'trail-primary':{const t=trail(id);if(!state.ownedTrails.has(id)){if(t.price>state.wallet){showToast('Coins demo insufficienti.');break}state.wallet-=t.price;state.ownedTrails.add(id)}state.equippedTrail=id;closeModal();go('garage');showToast(`${t.name} equipaggiata nella demo.`);break}case'buy-bundle':{const b=BUNDLES.find(x=>x.id===id),price=bundlePrice(b);if(price>state.wallet){showToast('Coins demo insufficienti per questo bundle.');break}state.wallet-=price;state.ownedBikes.add(b.bike);state.ownedTrails.add(b.trail);state.bike=b.bike;state.equippedTrail=b.trail;closeModal();go('garage');showToast(`${b.name} aggiunto al Garage della demo.`);break}case'inspect-player':showPlayer(id);break;case'change-offer':state.tradeOffer=state.tradeOffer==='BananaBot'?'ToasterGoblin':'BananaBot';state.tradeStep=0;render();break;case'trade-next':if(state.tradeStep<2){state.tradeStep++;render()}else{state.tradeStep=0;render();showToast('Scambio simulato completato. Nessun oggetto reale è stato trasferito.')}break;case'trade-reset':state.tradeStep=0;render();showToast('Offerta della demo annullata.');break;case'battle-result':state.battleResult=true;render();break;case'battle-again':state.battleResult=false;render();break;case'royal-claim':state.claim=true;render();showToast('Ricompensa segnata come riscattata nella demo.');break;case'event-detail':openModal('Core Crash',`<p class="muted">Concept di pannello evento: countdown, regole, obiettivo e ricompense in primo piano.</p><div class="card card-pad"><span class="mini-label">SAMPLE EVENT</span><h3>Core Crash</h3><p>Le ricompense e il timer qui sono dati illustrativi.</p></div>`);break;case'egg-pool':closeModal();state.tabs.collection='brainrot';go('collection');showToast('Pool dimostrativo: sfoglia i Brainrot Tripo.');break}}
document.addEventListener('click',event=>{if(event.target===modalRoot){closeModal();return}const el=event.target.closest('button');if(!el)return;if(el.dataset.page){closeModal();go(el.dataset.page)}else if(el.dataset.tab){const [page,tab]=el.dataset.tab.split(':');state.tabs[page]=tab;if(state.page!==page)go(page);else render()}else if(el.dataset.detail){const [type,id]=el.dataset.detail.split(':');detail(type,id)}else if(el.dataset.action)action(el.dataset.action,el.dataset.id)});
document.addEventListener('input',event=>{if(!event.target.matches('[data-search]'))return;const query=event.target.value.trim().toLocaleLowerCase('it');document.querySelectorAll('#search-grid .product-card').forEach(el=>el.hidden=!el.dataset.name.includes(query))});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modalRoot.hidden)closeModal()});
document.getElementById('icon-grid').innerHTML=ICONS.map(([id,label])=>`<div class="icon-tile"><img src="icons/${id}.svg" alt=""><span>${label}</span></div>`).join('');
const initial=new URLSearchParams(location.search).get('page');if(initial&&pages[initial])state.page=initial;render();
